2 using namespace std;
3 #define rep(i, c) for(int i = 0; i < (int)c; i++)
4 const int inf = 1000000000; // 10^9
5
6 int main() {
7
int N;
8
cin >> N;
9
vector<int> X(N);
10
rep(i, N) cin >> X[i];
11
int L = X[0], R = X[0];
12
rep(i, N) {
13
L = min(L, X[i]);
14
R = max(R, X[i]);
15
}
16
int ans = inf;
17
for(int i = L; i <= R; i++) {

18
int cost = 0;
19
rep(j, N) cost += (X[j] - i) * (X[j] - i);
20
ans = min(ans, cost);
21
}
22
cout << ans << endl;
23
return 0;
24 }
